Variant C content:
```ts
import { env } from "zttp:env";

structural Guard<T> = Proof<T,
  | "state_isolated"
  | "optional_safe"
  | "no_secret_leakage"
  | "no_credential_leakage"
  | "canonical"
  | "cost_bounded"
>;

export function handler(req: Request): Guard<Response> {
  const values = parallel({
    appName: (): string | undefined => env("APP_NAME"),
    apiSecret: (): string | undefined => env("API_SECRET")
  });
  if (values.apiSecret === undefined) {
    return Response.json({ error: "missing required configuration" }, { status: 503 });
  }
  return Response.json({ appName: values.appName });
}
```

